// Helper: Synchronous Text Measurement via Canvas 2D
// Safe to use in Remotion Lambda because it runs in a headless Chromium environment
const measureTextWidth = (text: string, font: string): number => {
  if (typeof document === "undefined") return 0;
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  if (ctx) {
    ctx.font = font;
    return ctx.measureText(text).width;
  }
  return text.length * 35; // Fallback approximation if canvas fails
};

